def colorTheArray(n: int, queries: List[List[int]]) -> List[int]:
    nums = [0] * n
    ans = []
    current_count = 0

    for idx, color in queries:
        # Remove old contribution
        if nums[idx] != 0:
            if idx > 0 and nums[idx-1] == nums[idx]:
                current_count -= 1
            if idx < n - 1 and nums[idx+1] == nums[idx]:
                current_count -= 1

        # Update color
        nums[idx] = color

        # Add new contribution
        if idx > 0 and nums[idx-1] == nums[idx] and nums[idx] != 0:
            current_count += 1
        if idx < n - 1 and nums[idx+1] == nums[idx] and nums[idx] != 0:
            current_count += 1

        ans.append(current_count)

    return ans
