def shortestBeautifulSubstring(s: str, k: int):
    min_len = float('inf')
    res = ""
    n = len(s)

    for i in range(n):
        count = 0
        for j in range(i, n):
            if s[j] == '1':
                count += 1

            if count == k:
                length = j - i + 1
                substring = s[i : j + 1]
                if length < min_len:
                    min_len = length
                    res = substring
                elif length == min_len:
                    if substring < res:
                        res = substring
                break
    return res
