def numberOfStableArrays(zero: int, one: int, limit: int):
    MOD = 10**9 + 7

    # dp[i][j] 表示使用了 i 個 0 和 j 個 1 的穩定陣列數量
    dp = [[0] * (one + 1) for _ in range(zero + 1)]

    # 初始化：只有一個數字時，只要數量 <= limit 且符合條件（此處題目要求必須有 0 和 1）
    # 但我們從基礎狀態開始遞推即可。
    dp[0][0] = 1

    for i in range(zero + 1):
        for j in range(one + 1):
            if dp[i][j] == 0:
                continue

            # 嘗試在後面加入連續的 0 (數量從 1 到 limit)
            # 注意：不能超過總共擁有的 zero 數量
            for k in range(1, limit + 1):
                if i + k <= zero:
                    dp[i + k][j] = (dp[i + k][j] + dp[i][j]) % MOD
                else:
                    break

            # 嘗試在後面加入連續的 1 (數量從 1 到 limit)
            for k in range(1, limit + 1):
                if j + k <= one:
                    dp[i][j + k] = (dp[i][j + k] + dp[i][j]) % MOD
                else:
                    break

    # 上述邏輯會重複計算（例如 0...1... 和 1...0... 會被重複處理），
    # 正確的 DP 狀態應該是「最後一個數字是什麼」。
    # 重新修正標準做法：

    dp = [[0] * (one + 1) for _ in range(zero + 1)]
    dp[0][0] = 1

