            if dp[i][j] == 0: continue
            # 加入連續的 0
            for k in range(1, limit + 1):
                if i + k <= zero:
                    dp[i+k][j] = (dp[i+k][j] + dp[i][j]) % MOD # 這是不正確的，會導致重複計算。

    # 正確且最簡潔的 DP 寫法：
    # 令 dp[i][j] 為使用 i 個 0 和 j 個 1 的穩定陣列數量
    # 因為每次必須切換數字（或在限制內連續），我們可以用「最後一個塊」的概念。
    # 但更簡單的思考是：dp[i][j] = sum(dp[i-k][j]) + sum(dp[i][j-k]) 
    # 其中 k 從 1 到 limit。為了避免重複，當我們從 0 變成 1 時，必須確保之前的結尾是 0。

    # 重新實作：使用 dp[i][j] 表示最後一個數字是 0 的數量，dp2[i][j] 表示最後一個數字是 1 的數量
    dp0 = [[0] * (one + 1) for _ in range(zero + 1)]
    dp1 = [[0] * (one + 1) for _ in range(zero + 1)]

    # 初始化：基礎狀態（剛開始放一串 0 或 一串 1）
    for k in range(1, min(zero, limit) + 1): dp0[k][0] = 1
    for k in range(1, min(one, limit) + 1): dp1[0][k] = 1

    for i in range(zero + 1):
        for j in range(one + 1):
            # 如果最後一塊是 0，它前面必須是 1 的塊
            if i > 0:
                for k in range(1, min(i, limit) + 1):
                    dp0[i][j] = (dp0[i][j] + dp1[i-k][j]) % MOD
            # 如果最後一塊是 1，它前面必須是 0 的塊
            if j > 0:
