```python
def numberOfStableArrays(zero: int, one: int, limit: int):
    MOD = 10**9 + 7
    # dp[i][j] 表示使用 i 個 0 和 j 個 1 的穩定陣列數量
    dp = [[0] * (one + 1) for _ in range(zero + 1)]

    # 初始化：只有一塊數字的情況
    for i in range(1, min(zero, limit) + 1):
        dp[i][0] = 1
    for j in range(1, min(one, limit) + 1):
        dp[0][j] = 1

    for i in range(zero + 1):
        for j in range(one + 1):
            if i == 0 and j == 0: continue
            # 如果最後一塊是 0，前面必須是 1 的塊
            for k in range(1, limit + 1):
                if i - k >= 0:
                    dp[i][j] = (dp[i][j] + dp[i-k][j]) % MOD # 此處邏輯需微調以避免重複

    # 最終正確且簡潔的 DP：
    # 令 f(i, j) 為最後一個數字是 0 的數量，g(i, j) 為最後一個數字是 1 的數量
    f = [[0] * (one + 1) for _ in range(zero + 1)]
    g = [[0] * (one + 1) for _ in range(zero + 1)]

    for k in range(1, min(zero, limit) + 1): f[k][0] = 1
    for k in range(1, min(one, limit) + 1): g[0][k] = 1

    for i in range(zero + 1):
        for j in range(one + 1):
            if i > 0:
                for k in range(1, min(i, limit) + 1):
                    f[i][j] = (f[i][j] + g[i-k][j]) % MOD
            if j > 0:
                for k in range(1, min(j, limit) + 1):
                    g[i][j] = (g[i][j] + f[i][j-k]) % MOD

    return (f[zero][one] + g[zero][one]) % MOD
