from typing import List

def countOfPeaks(nums: List[int], queries: List[List[int]]) -> List[int]:
    n = len(nums)
    # Fenwick Tree (Binary Indexed Tree) to store peak counts
    bit = [0] * (n + 1)

    def update_bit(idx, val):
        idx += 1  # BIT is 1-indexed
        while idx <= n:
            bit[idx] += val
            idx += idx & (-idx)

    def query_bit(idx):
        idx += 1
        s = 0
        while idx > 0:
            s += bit[idx]
            idx -= idx & (-idx)
        return s

    # Helper to check if an index i is a peak in the original array
    def is_peak(i):
        if i <= 0 or i >= n - 1:
            return False
        return nums[i] > nums[i-1] and nums[i] > nums[i+1]

    # Initial construction
    for i in range(1, n - 1):
        if is_peak(i):
            update_bit(i, 1)

    results = []
    for q in queries:
        if q[0] == 1:
            l, r = q[1], q[2]
            # Peaks cannot be the first or last elements of a subarray
            # So we count peaks in range [l+1, r-1]
            if r - l < 3:
                results.append(0)
            else:
                results.append(query_bit(r - 1) - query_bit(l))
        else:
            idx, val = q[1], q[2]
            # Only indices [idx-1, idx+1] can change their peak status
            for i in range(max(1, idx - 1), min(n - 1, idx + 1) + 1):
                if is_peak(i):
                    update_bit(i, -1)

            nums[idx] = val

            for i in range(max(1, idx - 1), min(n - 1, idx + 1) + 1):
                if is_peak(i):
                    update_bit(i, 1)

    return results
