from typing import List

def countOfPeaks(nums: List[int], queries: List[List[int]]) -> List[int]:
    n = len(nums)
    bit = [0] * (n + 1)

    def update(i, delta):
        idx = i + 1
        while idx <= n:
            bit[idx] += delta
            idx += idx & (-idx)

    def query_sum(i):
        s = 0
        idx = i + 1
        while idx > 0:
            s += bit[idx]
            idx -= idx & (-idx)
        return s

    def is_peak(i):
        if i <= 0 or i >= n - 1:
            return False
        return nums[i] > nums[i-1] and nums[i] > nums[i+1]

    # Initial peaks (excluding boundaries of the whole array)
    for i in range(1, n - 1):
        if is_peak(i):
            update(i, 1)

    results = []
    for q in queries:
        if q[0] == 1:
            l, r = q[1], q[2]
            # A peak must have neighbors within [l, r]
            # So a peak at index i must satisfy l < i < r
            if r - l < 3:
                results.append(0)
            else:
                results.append(query_sum(r - 1) - query_sum(l))
        else:
            idx, val = q[1], q[2]
            # Check indices that could be affected by changing nums[idx]
            # These are idx-1, idx, and idx+1
            affected = set()
            for i in range(max(0, idx - 1), min(n, idx + 2)):
                if is_peak(i):
                    affected.add(i)

            # Remove old peak statuses
            for i in affected:
                update(i, -1)

            nums[idx] = val

            # Re-check and add new peak statuses
            for i in range(max(0, idx - 1), min(n, idx + 2)):
                if is_peak(i):
                    update(i, 1)

    return results
