from typing import List

def countOfPeaks(nums: List[int], queries: List[List[int]]) -> List[int]:
    n = len(nums)
    # BIT for range sum queries and point updates
    bit = [0] * (n + 1)

    def update_bit(idx, val):
        idx += 1  # 1-based indexing
        while idx <= n:
            bit[idx] += val
            idx += idx & (-idx)

    def query_bit(idx):
        idx += 1
        s = 0
        while idx > 0:
            s += bit[idx]
            idx -= idx & (-idx)
        return s

    # A peak at i exists if nums[i-1] < nums[i] > nums[i+1]
    # Note: Boundary elements cannot be peaks.
    def is_peak(i):
        if 0 < i < n - 1:
            return 1 if nums[i-1] < nums[i] and nums[i] > nums[i+1] else 0
        return 0

    # Initial BIT construction
    for i in range(n):
        if is_peak(i):
            update_bit(i, 1)

    results = []
    for q in queries:
        if q[0] == 1:
            l, r = q[1], q[2]
            # A peak at i must have neighbors within [l, r].
            # Therefore, a peak in nums[l...r] is any peak index i such that l < i < r.
            if r - l < 3:
                results.append(0)
            else:
                # Sum of peaks in range [l+1, r-1]
                res = query_bit(r - 1) - query_bit(l)
                results.append(max(0, res))
        else:
            idx, val = q[1], q[2]
            # Check indices that could be affected by changing nums[idx]
            # These are idx-1, idx, and idx+1
            affected = set()
            for i in range(idx - 1, idx + 2):
                if 0 <= i < n:
                    affected.add(i)

            for i in affected:
                if is_peak(i):
                    update_bit(i, -1)

            nums[idx] = val

            for i in affected:
                if is_peak(i):
                    update_bit(i, 1)

    return results
