from typing import List

def maximumEnergy(energy: List[int], k: int) -> int:
    n = len(energy)
    dp = [0] * n
    max_val = float('-inf')

    for i in range(n - 1, -1, -1):
        if i + k >= n:
            dp[i] = energy[i]
        else:
            dp[i] = energy[i] + dp[i + k]

        if dp[i] > max_val:
            max_val = dp[i]

    return max_val
