from typing import List

def minimumDifference(nums: List[int], k: int) -> int:
    ans = float('inf')
    # The number of distinct OR values ending at any index is small (at most 30-31)
    # because each bit can only be turned on once.
    current_ors = set()
    for x in nums:
        next_ors = {x}
        for prev in current_ors:
            next_ors.add(prev | x)
        current_ors = next_ors
        for val in current_ors:
            diff = abs(k - val)
            if diff < ans:
                ans = diff
    return int(ans)
