    # 先把所有小於 k 的正整數考慮進來
    # 對於每一對 (i, k-i)，我們只能選其中較小的那個（或不選）
    # 為了讓總和最小，我們從 1 開始往上選
    for i in range(1, k):
        if len(res) < n:
            # 如果加上 i 會與現有的元素組成 k，則跳過
            # 但因為我們是從小到大選，只要檢查 (k - i) 是否已經在裡面即可
            # 實際上更簡單的邏輯：對於每一對 (i, k-i)，只取較小的那個
            if i < k - i:
                res.append(i)
            elif i == k - i: # 當 k 是偶數且 i = k/2 時，只能選一個或不選
                # 這裡的 i 會被重複判斷，但因為是 if i < k-i 所以不會進入
                pass
            else: # i > k - i
                pass

    # 如果數量還不足 n，從 k 開始往後補（這些數字絕對不會組成 k）
    current = k
    while len(res) < n:
        res.append(current)
        current += 1

    return sum(res[:n])

# 優化後的更簡潔版本：
def minimumSum(n: int, k: int) -> int:
    ans = []
    # 第一階段：從 1 到 k-1 選取，但避開成對相加等於 k 的情況
    for i in range(1, k):
        if len(ans) < n and (i + (k - i) != k or i == k - i): # 這行邏輯不對，正確應為：
            pass

    # 正確邏輯：對於每一對 (x, k-x)，我們只拿較小的那個。若 x+x=k，只能拿一個 x。
    # 為了保證最小總和，我們先把所有 i < k/2 加入
    for i in range(1, (k // 2) + 1):
        if len(ans) < n and i != k - i:
            if i < k - i:
                ans.append(i)

    # 如果還沒滿，從 k 開始往後加
    curr = k
    while len(ans) < n:
        ans.append(curr)
        curr += 1

    # 因為上面的邏輯可能漏掉某些情況（例如 k 是偶數時的 k/2），重新簡化：
    res = []
    for i in range(1, k):
        if len(res) < n and (i < k - i or (i == k - i and i > 0)): # 此處邏輯仍不完美，換最直觀的：
            pass

    # 最標準且快速的寫法：
    final_res = []
    for i in range(1, k):
        if len(final_res) < n:
            # 只要確保沒人跟現有的加起來等於 k。
            # 因為我們從小到大加，只要檢查 (k - i) 是否已經在裡面即可。
            if (k - i) not in final_res:
                final_res.append(i)

    curr = k
    while len(final_res) < n:
        final_res.append(curr)
        curr += 1

    return sum(final_res[:n])

# 最終最精簡且正確的實作：
def minimumSum(n: int, k: int) -> int:
    res = []
    for i in range(1, k):
        if len(res) < n and (k - i) not in res:
            res.append(i)
    curr = k
    while len(res) < n:
        res.append(curr)
        curr += 1
    return sum(res[:n])
```

