from typing import List

def minOperationsToMakeMedianK(nums: List[int], k: int) -> int:
    nums.sort()
    n = len(nums)
    # Median index for even length is n // 2 (larger of the two)
    mid_idx = n // 2
    res = 0

    for i in range(mid_idx, n):
        if nums[i] < k:
            res += (k - nums[i])
        else:
            break # Optimization: elements are sorted

    # For numbers to the left of mid_idx that must be <= k
    # Note: The problem says median is k. To ensure k is at mid_idx, 
    # all elements to its right must be >= k and left must be <= k.
    # However, we only need to adjust elements that violate the sorted property 
    # relative to k being at mid_idx.

    # Correct logic for median k: 
    # Elements from mid_idx to n-1 should be >= k
    # Elements from 0 to mid_idx-1 should be <= k

    ans = 0
    for i in range(n):
        if i > mid_idx:
            if nums[i] < k:
                ans += (k - nums[i])
        elif i < mid_idx:
            if nums[i] > k:
                ans += (nums[i] - k)
        else: # i == mid_idx
            ans += abs(nums[i] - k)

    return ans

# Re-evaluating for "Shortest Working Solution" based on standard median logic:
def minOperationsToMakeMedianK(nums: List[int], k: int) -> int:
    nums.sort()
    mid = len(nums) // 2
    ans = 0
    for i in range(len(nums)):
        if i > mid:
            if nums[i] < k: ans += (k - nums[i])
        elif i == mid:
            ans += abs(nums[i] - k)
        else: # i < mid
            if nums[i] > k: ans += (nums[i] - k)
    return ans
