def countMatchingSubarrays(nums: List[int], pattern: List[int]) -> int:
    n = len(nums)
    m = len(pattern)
    count = 0

    # 子陣列長度為 m + 1，所以迴圈範圍到 n - m
    for i in range(n - m):
        match = True
        for k in range(m):
            prev = nums[i + k]
            curr = nums[i + k + 1]

            if pattern[k] == 1:
                if not (curr > prev):
                    match = False
                    break
            elif pattern[k] == 0:
                if not (curr == prev):
                    match = False
                    break
            elif pattern[k] == -1:
                if not (curr < prev):
                    match = False
                    break

        if match:
            count += 1

    return count
