from typing import List

def canSortArray(nums: List[int]) -> bool:
    # 核心邏輯：因為只能交換「位元數量相同」的相鄰元素，
    # 這意味著在排序後，原本處於同一「位元數量群組」中的數字，
    # 他們之間的相對順序必須與原始數組中的相對順序一致。

    # 先取得目標排序後的結果
    sorted_nums = sorted(nums)

    # 檢查每個位置上的數字
    for i in range(len(nums)):
        # 如果目前的數字跟排序後應該出現的數字不同
        if nums[i] != sorted_nums[i]:
            # 檢查這兩個數字的位元數量是否相同
            # 因為如果位元數量不同，它們就永遠無法透過交換來換到正確的位置
            if bin(nums[i]).count('1') != bin(sorted_nums[i]).count('1'):
                return False

    # 實際上更嚴謹的判斷是：對於所有具有相同位元數的數字，
    # 他們在原陣列中的相對順序，必須與他們在排序後陣列中的相對順序相同。

    # 建立一個字典，記錄每個位元數量對應的數字序列
    groups = {}
    for x in nums:
        count = bin(x).count('1')
        if count not in groups:
            groups[count] = []
        groups[count].append(x)

    # 建立排序後的陣列，並檢查相對順序
    sorted_nums = sorted(nums)
    sorted_groups = {}
    for x in sorted_nums:
        count = bin(x).count('1')
        if count not in sorted_groups:
            sorted_groups[count] = []
        sorted_groups[count].append(x)

    # 如果任何一個群組的順序不一致，就無法排序
    for count in groups:
        if groups[count] != sorted_groups.get(count, []):
            return False

    return True

# 簡化後的邏輯：其實只需檢查排序後，所有位元數相同的數字，
# 是否仍維持原本的相對順序即可。
def canSortArray(nums: List[int]) -> bool:
    sorted_nums = sorted(nums)
    # 建立一個 map 來存儲每個 bit count 對應的原始順序清單
    pos_map = {}
    for i, x in enumerate(nums):
        count = bin(x).count('1')
        if count not in pos_map:
            pos_map[count] = []
        pos_map[count].append(x)

    # 檢查排序後的陣列中，相同 bit count 的數字是否與原始順序一致
    # 我們用一個指標來追蹤每個群組目前讀取到哪一個元素
    indices = {}
    for i, x in enumerate(sorted_nums):
        count = bin(x).count('1')
        if count not in indices:
            indices[count] = 0

        # 如果排序後的數字與群組中預期的下一個數字不符，代表相對順序變了
        if x != pos_map[count][indices[count]]:
            return False
        indices[count] += 1

    return True
```

