def countSteppingNumbers(low: str, high: str) -> int:
    MOD = 10**9 + 7

    def solve(S):
        n = len(S)
        # dp[i][j][is_less][is_started]
        # i: index, j: current digit, is_less: tight constraint, is_started: leading zero status
        memo = {}

        def count(idx, last_digit, is_less, is_started):
            state = (idx, last_digit, is_less, is_started)
            if state in memo: return memo[state]

            if idx == n:
                return 1 if is_started else 0

            res = 0
            limit = int(S[idx]) if not is_less else 9

            for d in range(limit + 1):
                new_is_less = is_less or (d < limit)
                if not is_started:
                    if d == 0:
                        res += count(idx + 1, -1, new_is_less, False)
                    else:
                        res += count(idx + 1, d, new_is_less, True)
                else:
                    if abs(d - last_digit) == 1:
                        res += count(idx + 1, d, new_is_less, True)

            res %= MOD
            memo[state] = res
            return res

        return count(0, -1, False, False)

    # Count in [1, high] - Count in [1, low-1]
    # Since numbers are strings up to 10^100, we handle subtraction manually or use int conversion
    ans = (solve(high) - solve(str(int(low) - 1))) % MOD
    return ans
```

這是一個典型的 **數位動態規劃 (Digit DP)** 問題。由於數字長度可達 100 位，我們需要使用 DP 來計算從 `1` 到某個數 $N$ 的 stepping numbers 數量，然後用 `count(high) - count(low - 1)` 來得出答案。

```python
def countSteppingNumbers(low: str, high: str) -> int:
    MOD = 10**9 + 7

    def solve(n_str: str) -> int:
        if n_str == "0": return 1 # 包含 0 (但在題目範圍中 low >= 1，所以邏輯上會處理好)

        L = len(n_str)
        # memo[(index, last_digit, is_less, is_started)]
        memo = {}

        def dp(idx, last_digit, is_less, is_started):
            if idx == L:
                return 1 if is_started else 0

            state = (idx, last_digit, is_less, is_started)
            if state in memo:
                return memo[state]

            res = 0
            upper = int(n_str[idx]) if not is_less else 9

            # 如果還沒開始填入數字 (處理前導零)
            if not is_started:
                # 選 0 (繼續不開始)
                res = (res + dp(idx + 1, -1, True, False)) % MOD
                # 選 1~upper (正式開始)
                for d in range(1, upper + 1):
                    res = (res + dp(idx + 1, d, is_less or (d < upper), True)) % MOD
            else:
                # 已開始填數字，必須滿足 |d - last_digit| == 1
                for d in [last_digit - 1, last_digit + 1]:
                    if 0 <= d <= upper:
                        res = (res + dp(idx + 1, d, is_less or (d < upper), True)) % MOD

            memo[state] = res
            return res

        # 因為題目 low >= 1，我們計算 [1, n_str]，所以這裡會包含 0 的處理邏輯。
        # 但由於遞迴中 is_started 控制了，dp 會正確回傳 1~n_str 的數量。
        # 我們手動加回數字 "0" 的情況（如果需要），但此題範圍是正整數。
        return dp(0, -1, False, False)

    # 處理 low-1 的字串運算 (因為 low 可以很大，不能轉 int)
    def subtract_one(s: str) -> str:
        n = list(map(int, s))
        i = len(n) - 1
        while i >= 0:
            if n[i] > 0:
                n[i] -= 1
                break
            else:
                n[i] = 9
                i -= 1
        return "".join(map(str, n)).lstrip('0') or "0"

    # 答案為 count(high) - count(low-1)
    ans_high = solve(high)
    ans_low = solve(subtract_one(low))

    return (ans_high - ans_low + MOD) % MOD
```

