from typing import List

def countSubarrays(nums: List[int], k: int) -> int:
    ans = 0
    # current_ands stores {and_value: count} for subarrays ending at the previous index
    current_ands = {}

    for x in nums:
        next_ands = {x: 1}
        for val, count in current_ands.items():
            new_val = val & x
            next_ands[new_val] = next_ands.get(new_val, 0) + count

        ans += next_ands.get(k, 0)
        current_ands = next_ands

    return ans
