這是一個典型的 **最短路徑問題**（Shortest Path Problem）。因為字母只有 26 個，我們可以使用 **Floyd-Warshall演算法** 來計算所有字母之間的最小轉換成本。

```python
from typing import List

def minimumCost(source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
    # 初始化 26x26 的鄰接矩陣，用無限大表示不可達
    inf = float('inf')
    dist = [[inf] * 26 for _ in range(26)]

    # 每個字母到自身的轉換成本為 0
    for i in range(26):
        dist[i][i] = 0

    # 從給定的 cost 建立基礎邊權重（取最小的）
    for o, c, w in zip(original, changed, cost):
        u, v = ord(o) - ord('a'), ord(c) - ord('a')
        dist[u][v] = min(dist[u][v], w)

    # Floyd-Warshall 演算法計算所有字母間的最短路徑
    for k in range(26):
        for i in range(26):
            if dist[i][k] == inf: continue
            for j in range(26):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    total_cost = 0
    for s, t in zip(source, target):
        u, v = ord(s) - ord('a'), ord(t) - ord('a')
        if dist[u][v] == inf:
            return -1
        total_cost += dist[u][v]

    return int(total_cost)
