        if s2 in s1: return s1
        if s1 in s2: return s2
        best = None
        for i in range(min(len(s1), len(s2)), -1, -1):
            if s1.endswith(s2[:i]):
                candidate = s1 + s2[i:]
                if best is None or len(candidate) < len(best) or (len(candidate) == len(best) and candidate < best):
                    best = candidate
                return best # Since we go from largest i, first match is best length
        return s1 + s2

    # Corrected merge: find max overlap such that result is shortest then lexicographical
    def combine(s1, s2):
        if s2 in s1: return s1
        if s1 in s2: return s2
        best = None
        for i in range(min(len(s1), len(s2)), -1, -1):
            if s1.endswith(s2[:i]):
                res = s1 + s2[i:]
                if best is None or len(res) < len(best) or (len(res) == len(best) and res < best):
                    best = res
        return best

    candidates = []
    for p in itertools.permutations([a, b, c]):
        s1 = combine(p[0], p[1])
        s2 = combine(s1, p[2])
        candidates.append(s2)

    # Also need to consider cases where one string is inside another but not at ends
    # But 'combine' handles the "contained" part first. 
    # The permutations cover all orderings of overlaps.

    ans = min(candidates, key=lambda x: (len(x), x))
