```python
from collections import deque

def minimumOperationsToMakeEqual(x: int, y: int) -> int:
    # 使用 BFS  tìm 最短路徑
    queue = deque([(x, 0)])  # (當前數值, 操作次數)
    visited = {x}

    while queue:
        curr, steps = queue.popleft()

        if curr == y:
            return steps

        # 可能的操作方向
        next_steps = []
        if curr % 11 == 0:
            next_steps.append(curr // 11)
        if curr % 5 == 0:
            next_steps.append(curr // 5)
        next_steps.append(curr - 1)
        next_steps.append(curr + 1)

        for nxt in next_steps:
            # 限制範圍：避免數值變得過大（通常 y 的兩倍左右即可，此處設為 20000 以保險）
            if nxt not in visited and -100 < nxt < 20000:
                visited.add(nxt)
                queue.append((nxt, steps + 1))
```

