from typing import List

def specialPerm(nums: List[int]) -> int:
    n = len(nums)
    MOD = 10**9 + 7

    # Pre-calculate adjacency list (divisibility)
    adj = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0:
                adj[i].append(j)
                adj[j].append(i)

    # dp[mask][last_idx]
    dp = [[0] * n for _ in range(1 << n)]

    # Base case: single elements
    for i in range(n):
        dp[1 << i][i] = 1

    # Bitmask DP
    for mask in range(1, 1 << n):
        for u in range(n):
            if not (dp[mask][u]): continue
            for v in adj[u]:
                if not (mask & (1 << v)):
                    new_mask = mask | (1 << v)
                    dp[new_mask][v] = (dp[new_mask][v] + dp[mask][u]) % MOD

    return sum(dp[(1 << n) - 1]) % MOD
```

