```python
from typing import List

def stringIndices(wordsContainer: List[str], wordsQuery: List[str]) -> List[int]:
    # Trie node structure: {char: [next_node, length, index]}
    # We store the shortest length and earliest index at each suffix point.
    trie = {}

    for i, word in enumerate(wordsContainer):
        curr = trie
        # Reverse the word to treat suffix as prefix
        rev_word = word[::-1]
        for char in rev_word:
            if char not in curr:
                curr[char] = {}
            curr = curr[char]

            # Update node with shortest length and smallest index
            # If current node doesn't have metadata, or we find a shorter/earlier word
            if 'meta' not in curr:
                curr['meta'] = (len(word), i)
            else:
                length, idx = curr['meta']
                if len(word) < length:
                    curr['meta'] = (len(word), i)
                elif len(word) == length and i < idx:
                    curr['meta'] = (len(word), i)

    ans = []
    for query in wordsQuery:
        curr = trie
        best_meta = None
        rev_query = query[::-1]

        # Traverse the Trie with the reversed query
        for char in rev_query:
            if char in curr:
                curr = curr[char]
                # Every node reached is a common suffix, 
                # we keep updating to find the longest one.
                best_meta = curr['meta']
            else:
                break

        # If no common suffix was found, default to the best at root level
        # However, based on problem logic, if no match, any word is valid.
        # The "longest" empty suffix applies to all words in container.
        if best_meta is None:
            # Find the global best (shortest length, then smallest index)
            # This part can be optimized by pre-calculating the root's meta
            # but for standard cases, we find it once or use a dummy logic.
            pass 

        # To handle "no common suffix" correctly: 
        # The problem implies if no match, the longest common suffix is "".
        # We need to pre-calculate the best result for "" (the root's metadata).
        # Let's refine: we should store a 'root_meta' before the loop.

    # Refined logic for efficiency:
    return solve_optimized(wordsContainer, wordsQuery)

def solve_optimized(wordsContainer: List[str], wordsQuery: List[str]) -> List[int]:
    trie = {}
    root_meta = (float('inf'), float('inf'))

    for i, word in enumerate(wordsContainer):
        length = len(word)
        if length < root_meta[0] or (length == root_meta[0] and i < root_meta[1]):
            root_meta = (length, i)

        curr = trie
        rev_word = word[::-1]
        for char in rev_word:
            if char not in curr:
                curr[char] = {}
            curr = curr[char]
            if 'meta' not in curr:
                curr['meta'] = (length, i)
            else:
                l, idx = curr['meta']
                if length < l or (length == l and i < idx):
                    curr['meta'] = (length, i)

    results = []
    for query in wordsQuery:
        curr = trie
        best_meta = root_meta
        rev_query = query[::-1]
        for char in rev_query:
            if char in curr:
                curr = curr[char]
                best_meta = curr['meta']
            else:
                break
        results.append(best_meta[1])
    return results

# Final clean version to be used as requested:
def stringIndices(wordsContainer: List[str], wordsQuery: List[str]) -> List[int]:
    trie = {}
    root_meta = (float('inf'), float('inf'))

    for i, word in enumerate(wordsContainer):
        length = len(word)
        if length < root_meta[0] or (length == root_meta[0] and i < root_meta[1]):
            root_meta = (length, i)

