def findPrimePairs(n: int):
    if n < 4: return []

    # Sieve of Eratosthenes
    primes = [True] * (n + 1)
    primes[0] = primes[1] = False
    for p in range(2, int(n**0.5) + 1):
        if primes[p]:
            for i in range(p * p, n + 1, p):
                primes[i] = False

    res = []
    # x <= y and x + y == n => x <= n/2
    for x in range(2, (n // 2) + 1):
        y = n - x
        if primes[x] and primes[y]:
            res.append([x, y])
    return res
