from typing import List

def shortestDistanceAfterQueries(n: int, queries: List[List[int]]) -> List[int]:
    # dist[i][j] is the shortest path from i to j
    dist = [[float('inf')] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
        if i + 1 < n:
            dist[i][i+1] = 1

    # Initial Floyd-Warshall to handle base roads (though only dist[i][i+1]=1 is needed)
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    results = []
    for u, v in queries:
        # Update distance based on new road (u -> v) with weight 1
        if dist[u][v] > 1:
            dist[u][v] = 1
            # Re-run Floyd-Warshall update logic for this specific edge
            for i in range(n):
                for j in range(n):
                    dist[i][j] = min(dist[i][j], dist[i][u] + 1 + dist[v][j])
        results.append(dist[0][n-1])
    return results
```

