def validStrings(n: int):
    res = []
    def backtrack(s):
        if len(s) == n:
            res.append(s)
            return
        for char in ["0", "1"]:
            if not (len(s) >= 2 and s[-2] == "0" and char == "0"):
                backtrack(s + char)

    backtrack("")
    return res
```

