from typing import List

def lengthOfLongestSubsequence(nums: List[int], target: int) -> int:
    # dp[i] stores the max length of a subsequence that sums to i
    # Initialize with -infinity, except for sum 0 which has length 0
    dp = [-float('inf')] * (target + 1)
    dp[0] = 0

    for x in nums:
        for j in range(target, x - 1, -1):
            if dp[j - x] != -float('inf'):
                dp[j] = max(dp[j], dp[j - x] + 1)

    return int(dp[target]) if dp[target] != -float('inf') else -1
```

