from typing import List

def lengthOfLongestSubsequence(nums: List[int], target: int) -> int:
    # dp[i] stores the maximum length of a subsequence that sums to i
    # Initialize with -1, except for sum 0 which has length 0
    dp = [-1] * (target + 1)
    dp[0] = 0

    for num in nums:
        for i in range(target, num - 1, -1):
            if dp[i - num] != -1:
                dp[i] = max(dp[i], dp[i - num] + 1)

    return dp[target] if dp[target] != -1 else -1
