def minAnagramLength(s: str):
    n = len(s)
    # 從最短可能的長度 1 開始嘗試到 n
    for length in range(1, n + 1):
        if n % length == 0:
            # 計算第一個區塊的字元頻率
            target_counts = [0] * 26
            for i in range(length):
                target_counts[ord(s[i]) - ord('a')] += 1

            possible = True
            # 檢查接下來每個區塊是否都是第一個區塊的字母異位詞 (Anagram)
            for i in range(length, n, length):
                current_counts = [0] * 26
                for j in range(i, i + length):
                    current_counts[ord(s[j]) - ord('a')] += 1

                if current_counts != target_counts:
                    possible = False
                    break

            if possible:
                return length
    return n
```

