from collections import Counter

def minAnagramLength(s: str) -> int:
    n = len(s)
    # 從最短可能的長度開始檢查（從 1 到 n）
    for length in range(1, n + 1):
        if n % length == 0:
            # 計算第一個區塊的字元頻率
            target_count = Counter(s[:length])
            possible = True

            # 檢查接下來每個區塊是否都是 anagram
            for i in range(length, n, length):
                current_count = Counter(s[i : i + length])
                if current_count != target_count:
                    possible = False
                    break

            if possible:
                return length
    return n
```

