            # 檢查是否符合題意：每個區塊的字母頻率必須相同
            target_counts = Counter(s[:length])
            possible = True

            for i in range(length, n, length):
                current_counts = Counter(s[i : i + length])
                if current_counts != target_counts:
                    possible = False
                    break

            if possible:
