from typing import List

def minimumCost(target: str, words: List[str], costs: List[int]) -> int:
    n = len(target)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    # Pre-filter unique words to optimize if there are duplicates with higher costs
    word_map = {}
    for w, c in zip(words, costs):
        if w not in word_map or c < word_map[w]:
            word_map[w] = c

    # Optimization: Group words by their first character to reduce inner loop iterations
    buckets = {}
    for w, c in word_map.items():
        first_char = w[0]
        if first_char not in buckets:
            buckets[first_char] = []
        buckets[first_char].append((w, c))

    for i in range(n):
        if dp[i] == float('inf'):
            continue

        # Only check words starting with the character at target[i]
        char = target[i]
        if char in buckets:
            for w, c in buckets[char]:
                if target.startswith(w, i):
                    new_idx = i + len(w)
                    if dp[i] + c < dp[new_idx]:
                        dp[new_idx] = dp[i] + c

    return dp[n] if dp[n] != float('inf') else -1
```

