from typing import List

def minimumCost(target: str, words: List[str], costs: List[int]) -> int:
    n = len(target)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    # Pre-group words by their content to handle duplicates efficiently
    word_map = {}
    for w, c in zip(words, costs):
        if w not in word_map or c < word_map[w]:
            word_map[w] = c

    # DP: dp[i] is min cost to form target[:i]
    for i in range(n):
        if dp[i] == float('inf'):
            continue

        # Optimization: only check words that could potentially match starting at i
        # Since we need speed, we iterate through the unique word set
        for w, c in word_map.items():
            if target.startswith(w, i):
                new_pos = i + len(w)
                if dp[i] + c < dp[new_pos]:
                    dp[new_pos] = dp[i] + c

    return dp[n] if dp[n] != float('inf') else -1
