from typing import List

def sumImbalanceNumbers(nums: List[int]) -> int:
    n = len(nums)
    total_imbalance = 0
    for i in range(n):
        for j in range(i + 1, n + 1):
            subarray = sorted(nums[i:j])
            sub_len = len(subarray)
            if sub_len < 2:
                continue
            imbalance = 0
            for k in range(sub_len - 1):
                if subarray[k+1] - subarray[k] > 1:
                    imbalance += 1
            total_imbalance += imbalance
    return total_imbalance
```
